rules.bad:
const server = await start();
assert.equal(...); // gagal → server tidak pernah ditutup
await server.close();

rules.good:
// data.server.ts (server)
import { readFile } from "node:fs/promises";
export async function baca() { return readFile(...); }
// page.tsx
import { baca } from "./data.server.ts";
export async function loader() { return { isi: await baca() }; }

export function action({ formData }: PageActionContext) {
  const nama = String(formData.get("nama") ?? "").trim();
  if (nama.length < 2) return { errors: { nama: "Nama minimal 2 karakter" } };
  return { message: `Halo, ${nama}!` };
}
